import React from "react";
import type {
  ExperimentBench,
  EnergyBreakdown,
  TelemetryItem,
  BenchStepResult,
  BenchStageProps,
} from "../types";

export interface HarmonicParams extends Record<string, number> {
  stiffness: number;
  mass: number;
  amplitude: number;
  damping: number;
}

export interface HarmonicState {
  t: number;
  x: number;
  v: number;
  a: number;
  thermalEnergy: number;
  initialEnergy: number;
  waveTrail: { t: number; x: number }[];
  completed: boolean;
}

function renderShmArrow(
  x1: number,
  y: number,
  dx: number,
  color: string,
  label: string,
  labelAbove: boolean,
) {
  if (Math.abs(dx) < 5) return null;
  const x2 = x1 + dx;
  const dir = Math.sign(dx);
  const bx = x2 - dir * 7;
  return (
    <g>
      <line
        x1={x1}
        y1={y}
        x2={bx}
        y2={y}
        stroke={color}
        strokeWidth="2"
        strokeLinecap="round"
      />
      <polygon
        points={`${x2},${y} ${bx},${y - 3.2} ${bx},${y + 3.2}`}
        fill={color}
      />
      <text
        x={x1 + dx * 0.5}
        y={labelAbove ? y - 7 : y + 14}
        textAnchor="middle"
        fill={color}
        fontSize="11"
        fontWeight="600"
        style={{
          paintOrder: "stroke",
          stroke: "var(--ml-canvas-bg)",
          strokeWidth: "3.5px",
        }}
      >
        {label}
      </text>
    </g>
  );
}

