 */

import React from "react";
import type {
  ExperimentBench,
  EnergyBreakdown,
  TelemetryItem,
  BenchStepResult,
  BenchStageProps,
} from "../types";

export interface ProjectileParams extends Record<string, number> {
  launchAngleDeg: number;
  initialSpeed: number;
  towerHeight: number;
  gravity: number;
  targetDistance: number;
}

export interface ProjectilePoint {
  t: number;
  x: number;
  y: number;
  freeFallY: number;
}

export interface ProjectileState {
  t: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  freeFallY: number;
  freeFallVy: number;
  maxHeight: number;
  trail: ProjectilePoint[];
  strobes: ProjectilePoint[];
  lastStrobeAt: number;
  hitTarget: boolean;
  completed: boolean;
}

const BALL_MASS = 1.0;

function renderArrow(
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  color: string,
  label: string,
  offsetX: number,
  offsetY: number,
  anchor: "start" | "middle" | "end" = "start",
) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len = Math.hypot(dx, dy);
  if (len < 4) return null;
  const ux = dx / len;
  const uy = dy / len;
  const px = -uy;
  const py = ux;
  const headLen = 7;
  const headW = 3.2;
  const bx = x2 - ux * headLen;
  const by = y2 - uy * headLen;

  return (
    <g>
      <line
        x1={x1}
        y1={y1}
        x2={bx}
        y2={by}
        stroke={color}
        strokeWidth="2"
        strokeLinecap="round"
      />
      <polygon
        points={`${x2},${y2} ${bx + px * headW},${by + py * headW} ${
          bx - px * headW
        },${by - py * headW}`}
        fill={color}
      />
      <text
        x={x2 + offsetX}
        y={y2 + offsetY}
        textAnchor={anchor}
        fill={color}
        fontSize="11"
        fontWeight="600"
        style={{
          paintOrder: "stroke",
          stroke: "var(--ml-canvas-bg)",
          strokeWidth: "3.5px",
        }}
      >
        {label}
      </text>
    </g>
  );
}

