:root {
  color-scheme: light dark;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", Roboto, "PingFang SC", sans-serif;
  font-synthesis: none;

  /* 现代克制的中性色调色板，兼容明暗主题 */
  --ml-bg: light-dark(#f8fafc, #0b0f17);
  --ml-surface: light-dark(#ffffff, #111827);
  --ml-surface-subtle: light-dark(#f1f5f9, #161f30);
  --ml-text: light-dark(#0f172a, #f1f5f9);
  --ml-text-muted: light-dark(#64748b, #94a3b8);
  --ml-text-dim: light-dark(#94a3b8, #64748b);

  /* 唯一主强调色 */
  --ml-primary: light-dark(#0284c7, #38bdf8);
  --ml-primary-soft: light-dark(rgba(2, 132, 199, 0.08), rgba(56, 189, 248, 0.12));

  /* 物理向量语义色（仅用于表达物理含义） */
  --ml-force-g: light-dark(#d97706, #fbbf24);
  --ml-force-n: light-dark(#059669, #34d399);
  --ml-force-f: light-dark(#e11d48, #fb7185);
  --ml-force-ext: light-dark(#0284c7, #38bdf8);
  --ml-force-comp: light-dark(#64748b, #94a3b8);

  /* 能量分布语义色 */
  --ml-ek: light-dark(#10b981, #34d399);
  --ml-ep: light-dark(#0284c7, #38bdf8);
  --ml-q: light-dark(#f43f5e, #fb7185);

  /* 画布与实验器材低对比配色 */
  --ml-canvas-bg: light-dark(#ffffff, #0f172a);
  --ml-canvas-grid: light-dark(rgba(15, 23, 42, 0.045), rgba(248, 250, 252, 0.045));
  --ml-canvas-ground: light-dark(#cbd5e1, #334155);
  --ml-ramp-surface: light-dark(#f1f5f9, #182234);
  --ml-ramp-edge: light-dark(#cbd5e1, #334155);
  --ml-block-fill: light-dark(#f59e0b, #f59e0b);
  --ml-block-stroke: light-dark(#d97706, #fde68a);
  --ml-block-text: #ffffff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  background: var(--ml-bg);
  color: var(--ml-text);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.14s ease, color 0.14s ease, opacity 0.14s ease;
}

button:disabled {
  opacity: 0.38;
  cursor: default;
}

/* 整体布局：去边框化，依靠留白与浅底色分区 */
.ml-app {
  width: 100%;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding: 16px 20px 20px;
  gap: 14px;
  background: var(--ml-bg);
}

/* 1. 顶栏：仅保留标题与分段切换器 */
.ml-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.ml-title {
  font-size: 16px;
  font-weight: 650;
  color: var(--ml-text);
  letter-spacing: -0.02em;
}

.ml-bench-tabs {
  display: inline-flex;
  background: var(--ml-surface-subtle);
  padding: 3px;
  border-radius: 8px;
  gap: 2px;
}

.ml-tab-btn {
  padding: 5px 12px;
  border-radius: 6px;
  color: var(--ml-text-muted);
  font-size: 12px;
  font-weight: 550;
  white-space: nowrap;
}

.ml-tab-btn:hover:not(.is-active) {
  color: var(--ml-text);
}

.ml-tab-btn.is-active {
  background: var(--ml-surface);
  color: var(--ml-text);
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
}

/* 2. 主工作区双栏 */
.ml-workspace {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 256px;
  gap: 20px;
  align-items: start;
}

@media (max-width: 820px) {
  .ml-workspace {
    grid-template-columns: 1fr;
  }
}

.ml-stage-column {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

/* 实验画布容器：干净无描边，让实验画面成为视觉焦点 */
.ml-canvas-surface {
  background: var(--ml-canvas-bg);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.ml-stage-svg {
  width: 100%;
  height: auto;
  min-height: 350px;
  max-height: 460px;
  display: block;
}

/* 画布正下方集中操作栏 */
.ml-transport-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  padding: 10px 16px;
  background: var(--ml-surface);
}

.ml-transport-main {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

/* 唯一主操作按钮 */
.ml-play-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 16px;
  border-radius: 7px;
  background: var(--ml-primary);
  color: #ffffff;
  font-size: 12.5px;
  font-weight: 600;
}

.ml-play-btn:hover {
  opacity: 0.92;
}

.ml-play-btn.is-running {
  background: var(--ml-text);
  color: var(--ml-surface);
}

/* 轻量无描边辅助按钮 */
.ml-ghost-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 10px;
  border-radius: 6px;
  color: var(--ml-text-muted);
  font-size: 12px;
  font-weight: 500;
}

.ml-ghost-btn:hover:not(:disabled) {
  background: var(--ml-surface-subtle);
  color: var(--ml-text);
}

.ml-ghost-btn.is-active {
  background: var(--ml-primary-soft);
  color: var(--ml-primary);
  font-weight: 600;
}

/* 右侧轻量视图开关 */
.ml-transport-toggles {
  display: flex;
