  background: var(--ml-primary-soft);
  color: var(--ml-primary);
  font-weight: 600;
}

.ml-toggle-pill.is-icon {
  padding: 5px 8px;
}

/* 3. 关键物理量读数条：无边框、大字号数字、弱化单位 */
.ml-readout-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(115px, 1fr));
  gap: 12px 20px;
  padding: 4px 4px;
}

.ml-readout-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ml-readout-label {
  font-size: 11.5px;
  color: var(--ml-text-muted);
  font-weight: 450;
}

.ml-readout-sym {
  font-style: normal;
  color: var(--ml-text-dim);
  margin-left: 2px;
}

.ml-readout-val {
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-variant-numeric: tabular-nums;
}

.ml-readout-val strong {
  font-size: 20px;
  font-weight: 650;
  color: var(--ml-text);
  letter-spacing: -0.02em;
}

.ml-readout-val small {
  font-size: 11.5px;
  color: var(--ml-text-dim);
  font-weight: 500;
}

/* 4. 次级信息区：能量守恒与可折叠公式原理 */
.ml-secondary-area {
  background: var(--ml-surface-subtle);
  border-radius: 10px;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
